import { useEffect, useRef } from 'react'
import { Button } from '@/components/ui/button'
import { X } from 'lucide-react'

interface MobileFormDrawerProps {
  isOpen: boolean
  onClose: () => void
  title: string
  children: React.ReactNode
  primaryAction?: {
    label: string
    onClick: () => void
    disabled?: boolean
    loading?: boolean
  }
  secondaryAction?: {
    label: string
    onClick: () => void
    disabled?: boolean
  }
}

export function MobileFormDrawer({
  isOpen,
  onClose,
  title,
  children,
  primaryAction,
  secondaryAction
}: MobileFormDrawerProps) {
  const backdropRef = useRef<HTMLDivElement>(null)
  const drawerRef = useRef<HTMLDivElement>(null)

  // Handle escape key and body scroll prevention
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && isOpen) {
        onClose()
      }
    }

    if (isOpen) {
      document.addEventListener('keydown', handleKeyDown)

      // Prevent body scroll when drawer is open - use proper React pattern
      const originalOverflow = document.body.style.overflow
      const originalPaddingRight = document.body.style.paddingRight

      // Calculate scrollbar width to prevent layout shift
      const scrollbarWidth = window.innerWidth - document.documentElement.clientWidth
      document.body.style.overflow = 'hidden'
      if (scrollbarWidth > 0) {
        document.body.style.paddingRight = `${scrollbarWidth}px`
      }

      // Auto-focus first input after animation
      const timer = setTimeout(() => {
        const firstInput = drawerRef.current?.querySelector('input, select, textarea') as HTMLInputElement
        if (firstInput) {
          firstInput.focus()
        }
      }, 300)

      return () => {
        document.removeEventListener('keydown', handleKeyDown)
        // Restore original styles properly
        document.body.style.overflow = originalOverflow
        document.body.style.paddingRight = originalPaddingRight
        clearTimeout(timer)
      }
    }
  }, [isOpen, onClose])

  // Handle backdrop click
  const handleBackdropClick = (event: React.MouseEvent) => {
    if (event.target === backdropRef.current) {
      onClose()
    }
  }

  if (!isOpen) return null

  return (
    <div
      ref={backdropRef}
      className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50 md:items-center"
      onClick={handleBackdropClick}
      role="dialog"
      aria-modal="true"
      aria-labelledby="drawer-title"
    >
      <div
        ref={drawerRef}
        className="bg-white w-full max-h-[90vh] overflow-hidden flex flex-col mobile-form-drawer md:rounded-lg md:max-w-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-border/40 flex-shrink-0">
          <h2 id="drawer-title" className="text-lg font-semibold tracking-tight">{title}</h2>
          <Button

