async function findGearForm(page) {
  await page.waitForTimeout(1500) // Give form time to appear

  const possibleContainers = [
    page.locator('[role="dialog"]'),
    page.locator('.modal'),
    page.locator('[data-state="open"]'),
    page.locator('form'),
  ]

  for (const container of possibleContainers) {
    try {
      if (await container.count() === 1 && await container.isVisible()) {
        return container
      }
    } catch (error) {
      // Skip containers that cause strict mode violations
      continue
    }
  }

  // Fallback - just get the first form if it exists
  const anyForm = page.locator('form')
  if (await anyForm.count() > 0) {
    return anyForm.first()
  }

  throw new Error('Form dialog/container not found')
}

