  const inputs = form.locator('input')
  const inputCount = await inputs.count()

  if (inputCount >= 1 && data.name) {
    await inputs.nth(0).fill(data.name)
  }

  if (inputCount >= 2 && data.weight) {
    await inputs.nth(1).fill(data.weight)
  }

  // Fill additional fields if they exist
  if (inputCount >= 3 && data.brand) {
    await inputs.nth(2).fill(data.brand)
  }
}

