async function fillGearForm(form, data) {
  // Fill by specific input identifiers
  if (data.name) {
    const nameInput = form.locator('input[name="name"], input[placeholder*="name" i]').first()
    await nameInput.fill(data.name)
  }

  if (data.weight) {
    const weightInput = form.locator('input[name="weight"], input[placeholder*="weight" i]').first()
    await weightInput.fill(data.weight)
  }

  if (data.brand) {
    const brandInput = form.locator('input[name="brand"], input[placeholder*="brand" i]').first()
    if (await brandInput.count() > 0) {
      await brandInput.fill(data.brand)
    }
  }

