import { useState, useEffect } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Skeleton } from '@/components/ui/skeleton'
import {
  Plus,
  Search,
  Package,
  Filter,
  ChevronDown,
  LayoutGrid,
  TableProperties
} from 'lucide-react'
import { createGearRepository } from '@/lib/gearRepository'
import { captureError } from '@/lib/sentry'
import { toast } from '@/hooks/useToast'
import { GearTable, type SortField, type SortDirection } from '@/components/gear/GearTable'
import { GearCard } from '@/components/gear/GearCard'
import { ViewModeSelector } from '@/components/gear/ViewModeSelector'
import { WeightUnitSelector } from '@/components/gear/WeightUnitSelector'
import { EditGearForm } from '@/components/gear/EditGearForm'
import { DeleteDialog } from '@/components/gear/DeleteDialog'
import { AddGearFormWrapper } from '@/components/gear/AddGearFormWrapper'
import { AppHeader } from '@/components/navigation/AppHeader'
import { CategoryFilterDropdown } from '@/components/gear/CategoryFilterDropdown'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'
export type ViewMode = 'compact' | 'default' | 'comfortable'
export function GearCloset() {
  const { user } = useAuth()
  const [items, setItems] = useState<GearItem[]>([])
  const [filteredItems, setFilteredItems] = useState<GearItem[]>([])
  const [sortedItems, setSortedItems] = useState<GearItem[]>([])
  const [loading, setLoading] = useState(true)
  const [viewMode, setViewMode] = useState<ViewMode>(() => {
    const saved = localStorage.getItem('gearViewMode')
    // Default to comfortable (card) view on mobile for better touch experience
    const isMobile = window.innerWidth < 640
    return (saved as ViewMode) || (isMobile ? 'comfortable' : 'default')
  })
  const [weightUnit, setWeightUnit] = useState<WeightUnit>(() => {
    const saved = localStorage.getItem('gearWeightUnit')
    return (saved as WeightUnit) || 'g'
  })
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null)
  const [showAddForm, setShowAddForm] = useState(false)
  const [showMobileFilters, setShowMobileFilters] = useState(false)
  const [editingItem, setEditingItem] = useState<GearItem | null>(null)
  const [deletingItem, setDeletingItem] = useState<GearItem | null>(null)
  const [sortField, setSortField] = useState<SortField>('name')
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc')
  // Load gear items
  useEffect(() => {
    const loadGear = async () => {
      if (!user) return
      try {
        setLoading(true)
        const gearRepo = createGearRepository(user.id)
        const data = await gearRepo.list()
        setItems(data)
        setFilteredItems(data)
      } catch (error) {
        captureError(error as Error, {
          component: 'GearCloset',
          action: 'loadGear'
        })
        toast.error('Failed to load gear', 'Please refresh the page to try again.')
      } finally {
        setLoading(false)
      }
    }
    loadGear()
  }, [user])
  // Save view mode preference
  useEffect(() => {
    localStorage.setItem('gearViewMode', viewMode)
  }, [viewMode])
  // Save weight unit preference
  useEffect(() => {
    localStorage.setItem('gearWeightUnit', weightUnit)
  }, [weightUnit])
  // Filter items based on search and category
  useEffect(() => {
    let filtered = items
    if (searchTerm) {
      filtered = filtered.filter(item =>
        item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.brand?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.model?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.category.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.notes?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.description?.toLowerCase().includes(searchTerm.toLowerCase())
      )
    }
    if (selectedCategory) {
      filtered = filtered.filter(item => item.category === selectedCategory)
    }
    setFilteredItems(filtered)
  }, [items, searchTerm, selectedCategory])
  // Sort filtered items
  useEffect(() => {
    const sorted = [...filteredItems].sort((a, b) => {
      let aValue: string | number = a[sortField as keyof GearItem] as string | number
      let bValue: string | number = b[sortField as keyof GearItem] as string | number
      // Handle 'total' which is calculated
      if (sortField === 'total') {
        aValue = a.weight_grams * a.quantity
        bValue = b.weight_grams * b.quantity
      }
      // Handle null/undefined values
      if (aValue == null && bValue == null) return 0
      if (aValue == null) return sortDirection === 'asc' ? 1 : -1
      if (bValue == null) return sortDirection === 'asc' ? -1 : 1
      // Handle string comparison
      if (typeof aValue === 'string' && typeof bValue === 'string') {
        return sortDirection === 'asc'
          ? aValue.localeCompare(bValue)
          : bValue.localeCompare(aValue)
      }
      // Handle number comparison
      if (typeof aValue === 'number' && typeof bValue === 'number') {
        return sortDirection === 'asc'
          ? aValue - bValue
          : bValue - aValue
      }
      // Mixed types - convert to string for comparison
      const aStr = String(aValue)
      const bStr = String(bValue)
      return sortDirection === 'asc'
        ? aStr.localeCompare(bStr)
        : bStr.localeCompare(aStr)
    })
    setSortedItems(sorted)
  }, [filteredItems, sortField, sortDirection])
  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortDirection(prev => prev === 'asc' ? 'desc' : 'asc')
    } else {
      setSortField(field)
      setSortDirection('asc')
    }
  }
  // Calculate stats
  const totalWeight = items.reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)
  const baseWeight = items
    .filter(item => !item.worn && !item.consumable)
    .reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)
  const categories = Array.from(new Set(items.map(item => item.category)))
  // Calculate category counts for dropdown
  const categoryCounts = items.reduce((acc, item) => {
    acc[item.category] = (acc[item.category] || 0) + 1
    return acc
  }, {} as Record<string, number>)
  const handleAdd = async (gear: Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    if (!user) return
    try {
      const gearRepo = createGearRepository(user.id)
      const newItem = await gearRepo.create(gear)
      setItems(prev => [...prev, newItem])
      setShowAddForm(false)
      toast.success(`✓ ${gear.name} added to your gear closet`)
    } catch (error) {
      captureError(error as Error, {
        component: 'GearCloset',
        action: 'handleAdd'
      })
      toast.error('Failed to add gear', 'Please try again.')
    }
  }
  const handleUpdate = async (id: string, updates: Partial<Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => {
    if (!user) return
    try {
      const gearRepo = createGearRepository(user.id)
      const updatedItem = await gearRepo.update(id, updates)
      setItems(prev => prev.map(item => item.id === id ? updatedItem : item))
      setEditingItem(null)
      toast.success('Gear updated successfully')
    } catch (error) {
      captureError(error as Error, {
        component: 'GearCloset',
        action: 'handleUpdate'
      })
      toast.error('Failed to update gear', 'Please try again.')
    }
  }
  const handleDelete = async (id: string) => {
    if (!user) return
    try {
      const gearRepo = createGearRepository(user.id)
      await gearRepo.delete(id)
      setItems(prev => prev.filter(item => item.id !== id))
      setDeletingItem(null)
      toast.success('Gear deleted successfully')
    } catch (error) {
      captureError(error as Error, {
        component: 'GearCloset',
        action: 'handleDelete'
      })
      toast.error('Failed to delete gear', 'Please try again.')
    }
  }
  return (
    <div className="min-h-screen bg-background">
      {/* Unified App Header */}
      <AppHeader
        title="Gear Closet"
        backTo="/dashboard"
