// Helper functions
async function findAddButton(page) {
  // Look for floating action button with Plus icon
  const floatingButton = page.locator('button[aria-label*="Add" i], button[aria-label*="gear" i]')

  if (await floatingButton.count() > 0) {
    return floatingButton.first()
  }

  // Fallback: look for any button with Plus icon
  const plusButton = page.locator('button').filter({
    has: page.locator('svg[class*="Plus"], svg path[d*="M12 5v14M5 12h14"]')
  })

  if (await plusButton.count() > 0) {
    return plusButton.first()
  }

  // Last resort: any floating button in corner
  const anyFloating = page.locator('button[class*="fixed"][class*="bottom"]')
  if (await anyFloating.count() > 0) {
    return anyFloating.first()
  }

  throw new Error('Add button not found')
}

