    if (await brandInput.count() > 0) {
      await brandInput.fill(data.brand)
    }
  }

  if (data.category) {
    const categorySelect = form.locator('select[name="category"], button[role="combobox"]').first()
    if (await categorySelect.count() > 0) {
      await categorySelect.click()
      await page.waitForTimeout(500)
      const option = page.locator(`[role="option"]:has-text("${data.category}")`)
      if (await option.count() > 0) {
        await option.click()
      }
    }
  }
}

