import { GearForm } from './GearForm'
import type { GearCategory } from '@/types/database'

interface GearFormData {
  name: string
  brand: string | null
  model: string | null
  category: GearCategory
  weight_grams: number
  quantity: number
  worn: boolean
  consumable: boolean
  notes: string | null
  price: number | null
  description: string | null
  image_url: string | null
}

interface AddGearFormProps {
  onAdd: (gear: GearFormData) => void
  onCancel?: () => void
  simplified?: boolean // For trip flow
  standalone?: boolean // Whether to show header and action buttons
}

export function AddGearForm({ onAdd, onCancel, simplified = false, standalone = true }: AddGearFormProps) {
  const handleSubmit = (data: GearFormData) => {
    onAdd(data)
  }

  return (
    <GearForm
      isEditing={false}
      onSubmit={handleSubmit}
      onCancel={onCancel}
      simplified={simplified}
      standalone={standalone}
    />
  )
}

