  if (data.name) {
    const nameInput = form.locator('input#name, input[placeholder*="Backpack" i]').first()
    await nameInput.waitFor({ state: 'visible' })
    await nameInput.fill(data.name)
  }

  if (data.weight) {
    const weightInput = form.locator('input#weight, input[placeholder="Weight"]').first()
    await weightInput.waitFor({ state: 'visible' })
    await weightInput.fill(data.weight)
  }

  if (data.brand) {
    const brandInput = form.locator('input#brand, input[placeholder*="brand" i], input[placeholder*="Gossamer" i]').first()
    if (await brandInput.count() > 0) {
      await brandInput.fill(data.brand)
    }
  }

  if (data.category) {
    // Category might be a select or custom dropdown
    const categorySelect = form.locator('#category, select, button[role="combobox"]').first()
    if (await categorySelect.count() > 0) {
      await categorySelect.click()
      await page.waitForTimeout(500)
      // Look for option in dropdown or select
      const option = page.locator(`[role="option"]:has-text("${data.category}"), option:has-text("${data.category}")`)
      if (await option.count() > 0) {
        await option.first().click()
      }
    }
  }
}

