import { useState, useRef, useEffect } from 'react'
import { GearCategory, WeightUnit } from '@/types/database'
import { convertToGrams, parseWeightInput, formatWeightWithUnit } from '@/utils/weight'
import { captureError } from '@/lib/sentry'
import { GEAR_CATEGORIES } from '@/constants/gear'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { SimpleSelect } from '@/components/ui/select'
import { ChevronDown, ChevronUp, Plus, Save } from 'lucide-react'
import { ImageUploadField } from './ImageUploadField'

interface GearFormData {
  name: string
  brand: string | null
  model: string | null
  category: GearCategory
  weight_grams: number
  quantity: number
  worn: boolean
  consumable: boolean
  notes: string | null
  price: number | null
  description: string | null
  image_url: string | null
}

interface GearFormProps {
  // For edit mode
  initialData?: Partial<GearFormData>
  isEditing?: boolean

  // Callbacks
  onSubmit: (data: GearFormData) => void | Promise<void>
  onCancel?: () => void

  // UI options
  simplified?: boolean // For trip flow
  standalone?: boolean // Whether to show header and action buttons
}

// Smart category suggestions based on item name
const categorySuggestions: Record<string, GearCategory> = {
  tent: 'Shelter',
  tarp: 'Shelter', 
  hammock: 'Shelter',
  footprint: 'Shelter',
  'sleeping bag': 'Sleep System',
  quilt: 'Sleep System',
  pad: 'Sleep System',
  pillow: 'Sleep System',
  stove: 'Cooking',
  pot: 'Cooking',
  spoon: 'Cooking',
  fuel: 'Cooking',
  filter: 'Water',
  bottle: 'Water',
  bladder: 'Water',
  purification: 'Water',
  jacket: 'Clothing',
  pants: 'Clothing',
  shirt: 'Clothing',
  socks: 'Clothing',
  phone: 'Electronics',
  battery: 'Electronics',
  charger: 'Electronics',
  headlamp: 'Electronics',
  'first aid': 'First Aid',
  bandage: 'First Aid',
  medication: 'First Aid',
  map: 'Navigation',
  compass: 'Navigation',
  gps: 'Navigation'
}

export function GearForm({ 
  initialData, 
  isEditing = false, 
  onSubmit, 
  onCancel, 
  simplified = false, 
  standalone = true 
}: GearFormProps) {
  // Core fields
  const [name, setName] = useState(initialData?.name || '')
  const [brand, setBrand] = useState(initialData?.brand || '')
  const [model, setModel] = useState(initialData?.model || '')
  const [category, setCategory] = useState<GearCategory>(initialData?.category || 'Other')
  const [quantity, setQuantity] = useState(initialData?.quantity || 1)

  // Weight handling
  const [weightValue, setWeightValue] = useState(() => {
    if (initialData?.weight_grams) {
      return initialData.weight_grams.toString()
    }
    return ''
  })
  const [weightUnit, setWeightUnit] = useState<WeightUnit>(initialData?.weight_grams ? 'g' : 'oz')

  // Advanced fields
  const [showAdvanced, setShowAdvanced] = useState(false)
  const [worn, setWorn] = useState(initialData?.worn || false)
  const [consumable, setConsumable] = useState(initialData?.consumable || false)
  const [price, setPrice] = useState(initialData?.price?.toString() || '')
  const [description, setDescription] = useState(initialData?.description || '')
  const [imageUrl, setImageUrl] = useState(initialData?.image_url || '')
  const [notes, setNotes] = useState(initialData?.notes || '')

  // UI state
  const [weightError, setWeightError] = useState('')
  const [loading, setLoading] = useState(false)
  const nameInputRef = useRef<HTMLInputElement>(null)

  // Auto-focus on mount (mobile-friendly)
  useEffect(() => {
    if (nameInputRef.current && !isEditing) {
      nameInputRef.current.focus()
    }
  }, [isEditing])

  // Smart category suggestion for new items
  useEffect(() => {
    if (name && !isEditing) {
      const lowerName = name.toLowerCase()
      for (const [keyword, suggestedCategory] of Object.entries(categorySuggestions)) {
        if (lowerName.includes(keyword)) {
          setCategory(suggestedCategory)
          break
        }
      }
    }
  }, [name, isEditing])

  // Parse weight input for smart entry (e.g., "12 oz", "340g")
  const handleWeightBlur = () => {
    const parsed = parseWeightInput(weightValue)
    if (parsed) {
      setWeightValue(parsed.value.toString())
      setWeightUnit(parsed.unit)
      setWeightError('')
    }
  }

  // Calculate weight in grams for display
  const getWeightInGrams = (): number => {
    const value = parseFloat(weightValue)
    if (isNaN(value)) return 0
    return Math.round(convertToGrams(value, weightUnit))
  }

  // Format weight preview in multiple units
  const getWeightPreview = (): string => {
    const grams = getWeightInGrams()
    if (grams === 0) return ''

    const units: WeightUnit[] = ['g', 'oz', 'lb', 'kg']
    const previews = units
      .filter(u => u !== weightUnit)
      .map(u => formatWeightWithUnit(grams, u))

    return `(${previews.join(' / ')})`
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)

    try {
      // Validate required fields
      if (!name.trim()) {
        nameInputRef.current?.focus()
        return
      }

      const weightNum = parseFloat(weightValue)
      if (isNaN(weightNum) || weightNum <= 0) {
        setWeightError('Please enter a valid weight')
        return
      }

      const weightGrams = getWeightInGrams()

      const formData: GearFormData = {
        name: name.trim(),
        brand: brand.trim() || null,
        model: model.trim() || null,
        category,
        weight_grams: weightGrams,
        quantity,
        worn,
        consumable,
        price: price ? parseFloat(price) : null,
        description: description.trim() || null,
        image_url: imageUrl.trim() || null,
        notes: notes.trim() || null
      }

      await onSubmit(formData)

      // Reset form only for add mode
      if (!isEditing) {
        setName('')
        setBrand('')
        setModel('')
        setWeightValue('')
        setCategory('Other')
        setQuantity(1)
        setWorn(false)
        setConsumable(false)
        setPrice('')
        setDescription('')
        setImageUrl('')
        setNotes('')
        setShowAdvanced(false)

        // Re-focus for quick entry
        nameInputRef.current?.focus()
      }

    } catch (error) {
      captureError(error as Error, {
        component: 'GearForm',
        action: 'handleSubmit',
        isEditing,
        formData: { 
          name, 
          brand, 
          weightValue, 
          weightUnit, 
          category, 
          quantity, 
          worn, 
          consumable, 
          price, 
          description, 
          imageUrl, 
          notes 
        }
      })
    } finally {
      setLoading(false)
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    // Cmd/Ctrl + Enter to submit
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
      handleSubmit(e)
    }
  }

  return (
    <form 
      onSubmit={handleSubmit}
      onKeyDown={handleKeyDown}
      className={standalone ? "bg-white rounded-lg shadow-sm border p-3 sm:p-4 md:p-6" : ""}
      data-gear-form
    >
      {standalone && (
        <div className="mb-3 sm:mb-4">
          <h2 className="text-base sm:text-lg font-semibold">
            {isEditing ? 'Edit Gear Item' : 'Add Gear'}
          </h2>
        </div>
      )}

      {/* Core Fields - Always Visible */}
      <div className="space-y-4">
        {/* Name and Weight - The two required fields */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          {/* Name */}
          <div className="flex flex-col gap-2">
            <Label htmlFor="name" className="text-sm font-medium">
              Name <span className="text-red-500">*</span>
            </Label>
            <Input
              ref={nameInputRef}
              id="name"
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="e.g., Backpack"
              required
              className="min-h-[44px]"
              autoComplete="off"
            />
          </div>

          {/* Weight */}
          <div className="flex flex-col gap-2">
            <div className="flex items-center justify-between">
              <Label htmlFor="weight" className="text-sm font-medium">
                Weight <span className="text-red-500">*</span>
              </Label>
              {getWeightPreview() && (
                <span className="text-sm text-muted-foreground">{getWeightPreview()}</span>
              )}
            </div>
            <div className="flex gap-2">
              <Input
                id="weight"
                type="number"
                step="0.1"
                value={weightValue}
                onChange={(e) => {
                  setWeightValue(e.target.value)
                  setWeightError('')
                }}
                onBlur={handleWeightBlur}
                placeholder="Weight"
                required
                className={`flex-1 min-h-[44px] ${weightError ? 'border-red-500' : ''}`}
                inputMode="decimal"
              />
              <SimpleSelect
                value={weightUnit}
                onChange={(value) => setWeightUnit(value as WeightUnit)}
                options={['g', 'oz', 'lb', 'kg']}
                className="min-w-[70px]"
              />
            </div>
            {weightError && (
              <p className="text-red-500 text-sm">{weightError}</p>
            )}
          </div>
        </div>

        {/* Brand and Model */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <div className="flex flex-col gap-2">
            <Label htmlFor="brand" className="text-sm font-medium">
              Brand
            </Label>
            <Input
              id="brand"
              type="text"
              value={brand}
              onChange={(e) => setBrand(e.target.value)}
              placeholder="e.g., Gossamer Gear"
              className="min-h-[44px]"
            />
          </div>
          <div className="flex flex-col gap-2">
            <Label htmlFor="model" className="text-sm font-medium">
              Model
            </Label>
            <Input
              id="model"
              type="text"
              value={model}
              onChange={(e) => setModel(e.target.value)}
              placeholder="e.g., Mariposa 60L"
              className="min-h-[44px]"
            />
          </div>
        </div>

        {/* Category and Options */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <div className="flex flex-col gap-2">
            <Label htmlFor="category" className="text-sm font-medium">
              Category
            </Label>
            <SimpleSelect
              value={category}
              onChange={(value) => setCategory(value as GearCategory)}
              options={GEAR_CATEGORIES}
            />
          </div>
          <div className="flex flex-col gap-2">
            <Label className="text-sm font-medium">Options</Label>
            <div className="flex gap-6 items-center min-h-[44px]">
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={worn}
                  onChange={(e) => setWorn(e.target.checked)}
                  className="min-h-[20px] min-w-[20px] rounded"
                />
                <span className="text-sm">Worn</span>
              </label>
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={consumable}
                  onChange={(e) => setConsumable(e.target.checked)}
                  className="min-h-[20px] min-w-[20px] rounded"
                />
                <span className="text-sm">Consumable</span>
              </label>
            </div>
          </div>
        </div>

        {/* Advanced Fields Toggle */}
        {!simplified && (
          <button
            type="button"
            onClick={() => setShowAdvanced(!showAdvanced)}
            className="flex items-center gap-2 text-sm text-gray-600 hover:text-gray-900 transition-colors"
          >
            {showAdvanced ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
            {showAdvanced ? 'Hide' : 'Show'} advanced options
          </button>
        )}

        {/* Advanced Fields */}
        {showAdvanced && !simplified && (
          <div className="space-y-4 pt-2 border-t">
            {/* Image Upload */}
            <ImageUploadField
              value={imageUrl}
              onChange={(url) => setImageUrl(url)}
            />

            {/* Quantity and Price */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="flex flex-col gap-2">
                <Label htmlFor="quantity" className="text-sm font-medium">
                  Quantity
                </Label>
                <Input
                  id="quantity"
                  type="number"
                  value={quantity}
                  onChange={(e) => setQuantity(parseInt(e.target.value) || 1)}
                  min="1"
                  className="min-h-[44px]"
                  inputMode="numeric"
                />
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="price" className="text-sm font-medium">
                  Price ($)
                </Label>
                <Input
                  id="price"
                  type="number"
                  step="0.01"
                  value={price}
                  onChange={(e) => setPrice(e.target.value)}
                  placeholder="0.00"
                  className="min-h-[44px]"
                  inputMode="decimal"
                />
              </div>
            </div>

            {/* Description and Notes */}
            <div className="space-y-4">
              <div className="flex flex-col gap-2">
                <Label htmlFor="description" className="text-sm font-medium">
                  Description
                </Label>
                <Textarea
                  id="description"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder="Detailed description..."
                  className="min-h-[80px]"
                />
              </div>

              <div className="flex flex-col gap-2">
                <Label htmlFor="notes" className="text-sm font-medium">
                  Notes
                </Label>
                <Textarea
                  id="notes"
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                  placeholder="Personal notes..."
                  className="min-h-[80px]"
                />
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Action Buttons - only show in standalone mode */}
      {standalone && (
        <div className="flex gap-2 mt-6">
          <Button type="submit" className="flex-1 md:flex-initial" disabled={loading}>
            {isEditing ? (
              <><Save className="h-4 w-4 mr-2" />Update Item</>
            ) : simplified ? (
              <><Plus className="h-4 w-4 mr-2" />Add & Continue</>
            ) : (
              <><Plus className="h-4 w-4 mr-2" />Add Gear</>
            )}
          </Button>
          {onCancel && (
            <Button
              type="button"
              variant="outline"
              onClick={onCancel}
              className="hidden md:inline-flex"
              disabled={loading}
            >
              Cancel
            </Button>
          )}
        </div>
      )}

      {/* Keyboard hint */}
      <p className="text-xs text-gray-500 mt-2 hidden md:block">
        Tip: Press Cmd+Enter to quickly {isEditing ? 'update' : 'add'} item
      </p>
    </form>
  )
}

